def is_valid(s: str) -> bool:
    stack = []
    pairs = {')': '(', '}': '{', ']': '['}
    for c in s:
        if c in pairs:
            top = stack.pop() if stack else '#'
            if pairs[c] != top:
                return False
        else:
            stack.append(c)
    return not stack
